 	   "deencap=s", "logmem", "learn=i", "reuse", "lint", "cache",
            "cachedir=s", "noisy", "scanprob=f",
-	   "server=s", "cs_max=i", "cs_timeout=i",
+	   "server=s", "cs_max=i", "cs_timeout=i", "cs_conn_retries=i",
 	   "cs_paths_only", "client=s", "cs_ssl", "cs_verbose",
 	   "before=s" => \\&deal_with_before_after,
 	   "after=s" => \\&deal_with_before_after,
@@ -1708,6 +1712,7 @@
 sub client_mode {
   $opt_cs_max ||= 1000;
   $opt_cs_timeout ||= 60 * 2;
+  $opt_cs_conn_retries ||= 60;            # 1 hour

   my($host, $port, $uri);

@@ -1741,7 +1746,6 @@
   }

   my $made_conn_once = 0;
-  my $conn_retries = 60;            # 1 hour

   # keep going until something stops us.
   while (1) {
@@ -1777,12 +1781,12 @@
       # if we haven't yet made a connection, keep retrying;
       # this is probably the server still in "scan stage"
       if (!$made_conn_once) {
-        if ($conn_retries-- >= 0) {
-          status('Failed to connect; sleeping for retry') if ($opt_noisy);
+        if ($opt_cs_conn_retries-- > 0) {
+          status('failed to connect, sleeping for retry') if ($opt_noisy);
           sleep 60;
           next;
         } else {
-          status('Failed to connect, giving up') if ($opt_noisy);
+          status('failed to connect, giving up') if ($opt_noisy);
           last;
         }
       }

On 21/10/2007, via RT golbeck @ cs. umd. edu  wrote:
> when you have a value for a hash, and then try to treat it as an array, it remembers
> the value. If we set it equal to something after pushing, the array is lost. I think
> the first behavior must be a bug.
>
>
> #!/usr/bin/perl
>
> #jen's perl bug.
> #xtqzkyo@cs.umd.edu
>
>
> %h = ();
> $h{1} = 3;
> push (@{$h{1}}, 2);
> push (@{$h{1}}, 4);

You're pushing values to the array @3 here.
Using "use strict" would prevent you to use named references like this.

> print $h{1};
> print "\\n";
> print @{$h{1}};
> print "\\n";
>
> $h{1} = 5;
>
> print $h{1};
> print "\\n";
> print @{$h{1}};

And here you're using array @5, which is a different array. Hence the
result you get is expected.

Note that hashes can't store arrays, only scalars. You probably want to
store arrays references in your hash instead.

